دالة خطوات_كولاتز(ن) {
    متغير خطوات = ٠
    طالما (ن != ١) {
        خطوات = خطوات + ١
        إذا (ن % ٢ == ٠) {
            ن = ن / ٢
        } وإلا {
            ن = ٣ * ن + ١
        }
    }
    ارجع خطوات
}

